// Sanctum: last_used_at при каждом запросе (здесь — не чаще раза в минуту, см. legacy.touchEvery).
func (q *Queries) MobileTokenTouch(ctx context.Context, arg MobileTokenTouchParams) error {
	_, err := q.db.Exec(ctx, mobileTokenTouch, arg.Now, arg.ClubID, arg.ID)
	return err
}

const mobileTokensRevokeUser = `-- name: MobileTokensRevokeUser :execrows
UPDATE mobile_api_tokens SET revoked_at = $1
WHERE user_id = $2 AND club_id IS NOT NULL AND revoked_at IS NULL
`

type MobileTokensRevokeUserParams struct {
	Now    *time.Time `json:"now"`
	UserID int64      `json:"user_id"`
}

// $user->tokens()->delete() (PasswordRecovery::reset()): токены аккаунта во всех клубах. Транзакция с app.user_id
// (политики mobile_token_owner_*); условие на club_id — только чтобы явно не трогать чужие строки.
func (q *Queries) MobileTokensRevokeUser(ctx context.Context, arg MobileTokensRevokeUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, mobileTokensRevokeUser, arg.Now, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const mobileUserClubs = `-- name: MobileUserClubs :many

SELECT m.id AS membership_id, m.club_id, c.name AS club_name, m.role
FROM club_memberships m
JOIN clubs c ON c.id = m.club_id
WHERE m.user_id = $1
ORDER BY c.name, c.id
`

type MobileUserClubsRow struct {
	MembershipID int64  `json:"membership_id"`
	ClubID       int64  `json:"club_id"`
	ClubName     string `json:"club_name"`
	Role         string `json:"role"`
}

// ---------------------------------------------------------------------------
// Вход, клубы аккаунта, профиль
// ---------------------------------------------------------------------------
// Клубы аккаунта (AuthController::clubList(): orderBy clubs.name) и id членства (login: ClubMembership::first() —
// первое по id). Транзакция с app.user_id (политика member_self_read).
func (q *Queries) MobileUserClubs(ctx context.Context, userID int64) ([]MobileUserClubsRow, error) {
	rows, err := q.db.Query(ctx, mobileUserClubs, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MobileUserClubsRow
	for rows.Next() {
		var i MobileUserClubsRow
		if err := rows.Scan(
			&i.MembershipID,
			&i.ClubID,
			&i.ClubName,
			&i.Role,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
